// Defines floordiv, the one summary function the SPEC.k claims below use (see
// contract/examples/reasoning.md for the matching worked trace of a different file).
module PRICING-VERIFICATION
  imports INT

  // floordiv(a, b): integer division rounding toward negative infinity, as Python's "//".
  // Guarded for positive divisors; this file only ever calls it with b = 100.
  syntax Int ::= floordiv(Int, Int) [function]
  rule floordiv(A, B) => A divInt B requires B >Int 0
endmodule
